        name: "Velocity Street Runner",
        price: "$164",
        rating: "4.8",
        badge: "Best seller",
        image: "https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=900&q=80",
        description: "Cushioned comfort, reflective accents, and all-day grip for every pace."
      },
      {
        category: "Accessories",
        name: "Contour Everyday Carry",
        price: "$118",
        rating: "4.7",
        badge: "Limited drop",
        image: "https://images.unsplash.com/photo-1523398002811-999ca8dec234?auto=format&fit=crop&w=900&q=80",
        description: "Minimalist organization with weather-ready nylon and modular pockets."
      },
      {
        category: "Home",
        name: "Lumen Ambient Speaker",
        price: "$198",
        rating: "5.0",
        badge: "Staff pick",
        image: "https://images.unsplash.com/photo-1511379938547-c1f69419868d?auto=format&fit=crop&w=900&q=80",
        description: "Premium room-filling audio wrapped in a sculptural soft-glow finish."
      }
    ];

    const deals = [
      {
        tag: "Flash deal",
        title: "Up to 40% off travel essentials",
        copy: "Streamlined duffels, packing cubes, and carry-on favorites built for lighter movement.",
        timer: "Ends in 12h 14m",
        progress: 76,
