        note: "Curated sets"
      },
      {
        tag: "Member exclusive",
        title: "Beauty routine upgrade event",
        copy: "Premium skincare, wellness tools, and self-care staples with early-access pricing.",
        timer: "Invite only",
        progress: 88,
        note: "Almost claimed"
      }
    ];

    const editorialStories = [
      {
        kicker: "Journal",
        title: "Five quiet-luxury staples that elevate everyday dressing",
        description: "A concise guide to tonal layering, refined textures, and pieces that work harder season after season.",
        image: "https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=80"
      },
      {
        kicker: "Spotlight",
        title: "Designing a calmer home with lighting that adapts to you",
        description: "See how adjustable warmth, sculptural lamps, and soft contrast create restorative spaces.",
        image: "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1200&q=80"
