        <aside class="glass-card spotlight-panel" aria-label="Featured story">
          <div class="spotlight-media" role="img" aria-label="Model styling a premium retail collection"></div>
          <div class="spotlight-copy">
            <h2>Tonight's spotlight: the monochrome capsule collection.</h2>
            <p>
