          <span class="editorial-kicker">${escapeHtml(kicker)}</span>
          <h3>${escapeHtml(title)}</h3>
          <p class="subtle">${escapeHtml(description)}</p>
          <a class="section-link" href="#home">Read story</a>
        </div>
      </article>
    `;

    const Newsletter = () => `
