            linkLabel: "See all product edits",
            id: "deals-title"
          })}
          <div class="grid deal-grid" id="deals">
            ${deals.map(DealCard).join("")}
          </div>
        </section>

        <section class="section" aria-labelledby="journal-title">
          ${SectionHeader({
            eyebrow: "Editorial",
            title: "Style notes, design ideas, and stories behind the products.",
            copy: "Blending retail inspiration with practical guidance, our editorial desk helps shoppers discover what to buy next and why it matters.",
            link: "#home",
            linkLabel: "Back to top",
            id: "journal-title"
          })}
          <div class="grid editorial-grid" id="journal">
            ${editorialStories.map(EditorialCard).join("")}
          </div>
        </section>

        ${Newsletter()}
        ${Footer()}
      </div>
    `;

    document.getElementById("app").innerHTML = App();

    document.querySelector(".newsletter-form").addEventListener("submit", (event) => {
      event.preventDefault();
      const button = event.currentTarget.querySelector("button");
      button.textContent = "You're in";
      button.disabled = true;
    });
  </script>
</body>
</html>
